import type { RealtimePrediction } from "tfl-ts"
import {
  ArrivalsBoardSkeleton,
  ArrivalsBoardView,
  resolveBusStopLetter,
  type ArrivalsBoardChromeProps,
  type ArrivalsBoardClassNames,
} from "@/components/tfl/arrivals/arrivals-board-view"
import {
  prepareBusArrivals,
  type BusArrivalsGroupBy,
  type BusArrivalsGroupSortBy,
  type BusArrivalsSortBy,
} from "@/lib/tfl/arrivals-prepare"

export type BusArrivalsBoardProps = ArrivalsBoardChromeProps & {
  /**
   * Normalised arrivals from `tfl.stopPoint.getArrivals` (`RealtimePrediction[]`).
   * Missing/`undefined` treated as an empty list. The board sorts this itself.
   */
  data?: readonly RealtimePrediction[]
  /**
   * `none` (default) is one flat list in arrival-time order, route chip on
   * every row. `route` groups by route with natural numeric headers.
   */
  groupBy?: BusArrivalsGroupBy
  /** Arrival order. Default `timeToStation` (global when flat, per route when grouped). */
  sortBy?: BusArrivalsSortBy
  /** Route-group order when `groupBy="route"`. Default `route` (9 before 18 before 205). */
  groupSortBy?: BusArrivalsGroupSortBy
  /** Cap on prediction rows after ordering. Headers do not count. */
  maxRows?: number
  /**
   * Visible arrivals per page. Grouped: per route, arrows on the route header.
   * Flat: the whole list, arrows in a trailing tile. Default 3.
   */
  pageSize?: number
  /**
   * Root classes, merged over the board container
   * (`data-slot="arrivals-board"`). Use `classNames` for board-width
   * arrangements — the root is the `arrivals` container itself.
   */
  className?: string
  /**
   * Layout-level class overrides for generated parts. Grouped: `groups`
   * arranges route sections against the board container (`/arrivals`).
   * Flat: `rows` styles the single time-ordered list. `subgroups` /
   * `subgroup` are rail-only — bus routes have no bound level.
   */
  classNames?: ArrivalsBoardClassNames
}

export const BusArrivalsBoardSkeleton = ({
  className,
  stopName,
  stopLetter,
}: {
  className?: string
  stopName?: string
  stopLetter?: string
} = {}) => (
  <ArrivalsBoardSkeleton
    mode="bus"
    className={className}
    stopName={stopName}
    stopLetter={stopLetter}
  />
)

/**
 * Bus arrivals board. Default is a flat time-ordered list with a route chip
 * on every row and the stop letter on the header. Fetching, caching, and
 * stop discovery stay in the app.
 *
 * Pass `groupBy="route"` for route sections (homepage and other explicit
 * grouped presentations).
 */
export const BusArrivalsBoard = ({
  data,
  groupBy = "none",
  sortBy = "timeToStation",
  groupSortBy = "route",
  maxRows = 16,
  pageSize = 3,
  stopLetter,
  loading = false,
  error = null,
  className,
  classNames,
  ...chrome
}: BusArrivalsBoardProps) => {
  const rows = data ?? []
  if (loading && rows.length === 0 && !error) {
    return (
      <BusArrivalsBoardSkeleton
        className={className}
        stopName={chrome.stopName}
        stopLetter={stopLetter}
      />
    )
  }

  const prepared = prepareBusArrivals({
    data: rows,
    groupBy,
    sortBy,
    groupSortBy,
    maxRows,
  })
  const resolvedStopLetter = resolveBusStopLetter(stopLetter, rows)

  return (
    <ArrivalsBoardView
      mode="bus"
      prepared={prepared}
      resolvedStopLetter={resolvedStopLetter}
      stopLetter={stopLetter}
      loading={loading}
      error={error}
      pageSize={pageSize}
      className={className}
      classNames={classNames}
      {...chrome}
    />
  )
}

export type { ArrivalsBoardClassNames }
export type {
  BusArrivalsGroupBy,
  BusArrivalsGroupSortBy,
  BusArrivalsSortBy,
} from "@/lib/tfl/arrivals-prepare"

import type { CSSProperties } from "react"
import type { RealtimePrediction } from "tfl-ts"
import { Loader2 } from "lucide-react"
import { TfLRoundel } from "@/components/tfl/brand/tfl-roundel"
import { StationName } from "@/components/tfl/station-name"
import {
  ARRIVALS_EMPTY_COPY,
  ARRIVALS_LINE_EMPTY_COPY,
  type ArrivalsEmptyKind,
} from "@/lib/tfl/arrivals-empty"
import type {
  ArrivalsPreparedBoard,
  ArrivalsPreparedGroup,
} from "@/lib/tfl/arrivals-prepare"
import { cn } from "@/lib/utils"
import { Skeleton } from "@/components/ui/skeleton"
import {
  ArrivalsBoundGroup,
  ArrivalsGroupHeader,
  ArrivalsPagedGroup,
  ArrivalsPagedList,
  type ArrivalsBoardClassNames,
} from "@/components/tfl/arrivals/arrivals-bound-group"

export type ArrivalsBoardMode = "rail" | "bus"

export type { ArrivalsBoardClassNames }
export {
  formatArrivalsCountdown,
  getArrivalsPlatformNumber,
} from "@/components/tfl/arrivals/arrivals-bound-group"

export type ArrivalsBoardChromeProps = {
  stopName: string
  /**
   * @deprecated Dev/meta NaPTAN id — not shown in the board UI. Kept for call-site compat.
   */
  stopPointId?: string
  /**
   * Bus stop letter (e.g. "G"). Prefer this over sniffing `platformName` on rows —
   * it is a stop property, not a per-arrival field.
   */
  stopLetter?: string
  /**
   * @deprecated Board heading is always `stopName`. Kept for call-site compat; ignored.
   */
  title?: string
  /** Semantic heading level for the stop name. Prefer `2` when embedded under a page `h1`. */
  headingLevel?: 1 | 2
  loading?: boolean
  /**
   * Fetch/render failure. Takes precedence over an empty list.
   * Prefer a short human line — raw API strings read as broken UI.
   */
  error?: string | null
  /** Optional poll / refresh label (e.g. "Poll #3 · every 15s"). */
  statusLabel?: string
  /**
   * Why the board has no rows when `error` is unset.
   * Resolve in the app (`resolveArrivalsEmptyKind`) from clock / offline / domain.
   */
  emptyKind?: ArrivalsEmptyKind
  /** Override copy for `emptyKind`. Prefer setting `emptyKind` instead. */
  emptyMessage?: string
}

/**
 * Baseline grid. Every block is a whole number of `--arrivals-unit` (0.5rem):
 * arrival row, board title, and line header are all 6 units, direction labels 6
 * (same as line names). Two boards side by side land on the same horizontal lines.
 * Override the vars on a wrapper to retune density.
 */
export const ARRIVALS_RHYTHM_VARS = {
  "--arrivals-unit": "0.5rem",
  "--arrivals-row": "calc(var(--arrivals-unit) * 6)",
} as CSSProperties

/**
 * Fixed tile box. Height is always exactly one rhythm row — content may clip,
 * but borders/bars must never grow the tile (`box-border` + overflow lock).
 */
export const ARRIVALS_TILE_CLASS =
  "box-border h-[var(--arrivals-row)] min-h-[var(--arrivals-row)] max-h-[var(--arrivals-row)] shrink-0 overflow-hidden [content-visibility:auto] [contain-intrinsic-size:auto_3rem]"

/** Line/route brand bar thickness — painted inside the tile via border-box. */
const LINE_BAR_BORDER_CLASS = "border-b-4"
const TITLE_CLASS =
  "[font-synthesis:none] [font-weight:var(--tfl-title-weight,400)] [letter-spacing:var(--tfl-title-tracking,0)]"

const LIST_RESET_CLASS = "m-0 ml-0 list-none space-y-0 p-0 [&>li]:mt-0"

/** Single-letter stop badge from bus `platformName` (e.g. "G"). */
export const getBusStopLetterFromPlatform = (
  platformName?: string
): string | null => {
  if (!platformName) return null
  const letter = platformName.trim()
  if (/^[A-Za-z]$/.test(letter)) return letter.toUpperCase()
  return null
}

export const resolveBusStopLetter = (
  stopLetter: string | undefined,
  rows: readonly RealtimePrediction[]
): string | null => {
  const fromProp = stopLetter?.trim().toUpperCase()
  if (fromProp) return fromProp
  for (const row of rows) {
    const letter = getBusStopLetterFromPlatform(row.platformName)
    if (letter) return letter
  }
  return null
}

const StopLetterBadge = ({ letter }: { letter: string }) => (
  <span
    data-line="buses"
    className="relative -top-px inline-flex size-5 shrink-0 items-center justify-center rounded-full bg-[var(--line-color)] align-middle text-[11px] leading-none font-bold text-[var(--line-ink)]"
    aria-label={`Stop ${letter}`}
  >
    {letter}
  </span>
)

export const ArrivalsBoardSkeleton = ({
  mode = "rail",
  className,
  stopName,
  stopLetter,
}: {
  mode?: ArrivalsBoardMode
  className?: string
  /** Known stop identity — paint immediately; do not wait on predictions. */
  stopName?: string
  stopLetter?: string
}) => (
  <div
    data-slot="arrivals-board"
    className={cn("@container/arrivals w-full space-y-2", className)}
    style={ARRIVALS_RHYTHM_VARS}
    aria-busy
    aria-label="Loading arrivals"
  >
    <div
      className={cn("flex min-w-0 items-center gap-x-3", ARRIVALS_TILE_CLASS)}
    >
      {stopName ? (
        <>
          <TfLRoundel
            variant={mode === "bus" ? "buses" : "underground"}
            className="size-[var(--arrivals-row)] shrink-0"
            aria-hidden
          />
          <p className={cn("min-w-0 flex-1 text-3xl", TITLE_CLASS)}>
            <span className="block min-w-0">
              <StationName
                name={stopName}
                layout="auto"
                maxLines={1}
                allowAbbreviation
                allowScaleDown
                className="justify-center leading-8"
              />
            </span>
          </p>
          {stopLetter ? <StopLetterBadge letter={stopLetter} /> : null}
        </>
      ) : (
        <Skeleton className="h-8 w-56 max-w-full" />
      )}
    </div>
    {mode === "bus" ? (
      <div>
        {Array.from({ length: 6 }).map((_, rowIndex) => (
          <div
            key={rowIndex}
            className={cn("flex items-center", ARRIVALS_TILE_CLASS)}
          >
            <Skeleton className="h-5 w-full" />
          </div>
        ))}
      </div>
    ) : (
      Array.from({ length: 2 }).map((_, sectionIndex) => (
        <div key={sectionIndex}>
          <div
            className={cn(
              "flex items-end",
              ARRIVALS_TILE_CLASS,
              LINE_BAR_BORDER_CLASS
            )}
          >
            <Skeleton className="mb-2 h-5 w-28" />
          </div>
          {Array.from({ length: 4 }).map((_, rowIndex) => (
            <div
              key={rowIndex}
              className={cn("flex items-center", ARRIVALS_TILE_CLASS)}
            >
              <Skeleton className="h-5 w-full" />
            </div>
          ))}
        </div>
      ))
    )}
  </div>
)

const GroupBody = ({
  group,
  mode,
  pageSize,
  classNames,
}: {
  group: ArrivalsPreparedGroup
  mode: ArrivalsBoardMode
  pageSize?: number
  classNames?: ArrivalsBoardClassNames
}) => {
  const labeledBounds = group.bounds.filter((bound) => bound.label)
  // `grid-cols-1` (not block) so consumer `grid-cols-*` variants merge cleanly.
  const subgroupsClassName = cn(
    LIST_RESET_CLASS,
    "grid grid-cols-1",
    classNames?.subgroups
  )

  if (!group.hasInformation && labeledBounds.length === 0) {
    return (
      <ul
        data-slot="arrivals-subgroups"
        className={subgroupsClassName}
        role="list"
      >
        <li
          data-slot="arrivals-row"
          className={cn(
            "flex items-center text-sm text-muted-foreground",
            ARRIVALS_TILE_CLASS
          )}
          aria-label={`${group.lineName}: ${ARRIVALS_LINE_EMPTY_COPY}`}
        >
          {ARRIVALS_LINE_EMPTY_COPY}
        </li>
      </ul>
    )
  }

  return (
    <ul
      data-slot="arrivals-subgroups"
      className={subgroupsClassName}
      role="list"
    >
      {group.bounds.map((bound, index) => (
        <ArrivalsBoundGroup
          key={bound.key}
          bound={bound}
          mode={mode}
          lineName={group.lineName}
          isLastBound={index === group.bounds.length - 1}
          pageSize={pageSize}
          classNames={classNames}
        />
      ))}
    </ul>
  )
}

export type ArrivalsBoardViewProps = ArrivalsBoardChromeProps & {
  mode: ArrivalsBoardMode
  prepared: ArrivalsPreparedBoard
  resolvedStopLetter?: string | null
  /**
   * Visible arrivals per page. Rail: per compass bound. Bus grouped: per
   * route. Bus flat: the whole list, with a trailing pager tile. Omit or `0`
   * to show the prepared rows.
   */
  pageSize?: number
  /**
   * Root classes, merged over the board container (`data-slot="arrivals-board"`).
   * The root *is* the `arrivals` container, so container-query variants here
   * query an outer context — put board-width arrangements on `classNames.groups`
   * instead.
   */
  className?: string
  /**
   * Layout-level class overrides for generated parts (`data-slot` per level).
   * CSS-first: arrange line sections via `groups`, bound columns via
   * `subgroups` — no JavaScript layout config.
   */
  classNames?: ArrivalsBoardClassNames
}

/**
 * Shared arrivals presentation. Domain boards prepare grouping and order;
 * this paints the already-resolved structure.
 */
export const ArrivalsBoardView = ({
  mode,
  prepared,
  stopName,
  resolvedStopLetter,
  headingLevel = 1,
  loading = false,
  error = null,
  statusLabel,
  emptyKind = "empty",
  emptyMessage,
  pageSize,
  className,
  classNames,
}: ArrivalsBoardViewProps) => {
  const TitleTag = headingLevel === 2 ? "h2" : "h1"
  const emptyCopy = emptyMessage ?? ARRIVALS_EMPTY_COPY[emptyKind]
  const showEmpty =
    !error &&
    !loading &&
    prepared.rows.length === 0 &&
    prepared.groups.length === 0

  return (
    <div
      data-slot="arrivals-board"
      className={cn("@container/arrivals w-full space-y-2", className)}
      style={ARRIVALS_RHYTHM_VARS}
    >
      <div
        className={cn("flex min-w-0 items-center gap-x-3", ARRIVALS_TILE_CLASS)}
      >
        <TfLRoundel
          variant={mode === "bus" ? "buses" : "underground"}
          className="size-[var(--arrivals-row)] shrink-0"
          aria-hidden
        />
        <TitleTag
          className={cn("min-w-0 flex-1 text-3xl", TITLE_CLASS)}
          aria-label={stopName}
        >
          <span className="block min-w-0" aria-hidden="true">
            <StationName
              name={stopName}
              layout="auto"
              maxLines={1}
              allowAbbreviation
              allowScaleDown
              className="justify-center leading-8"
            />
          </span>
        </TitleTag>
        {resolvedStopLetter || statusLabel || loading ? (
          <div className="flex shrink-0 items-center gap-x-2">
            {resolvedStopLetter ? (
              <StopLetterBadge letter={resolvedStopLetter} />
            ) : null}
            {statusLabel || loading ? (
              <p className="flex items-center gap-2 text-xs text-muted-foreground">
                {loading ? (
                  <>
                    <Loader2 className="size-3.5 animate-spin" aria-hidden />
                    Loading…
                  </>
                ) : (
                  statusLabel
                )}
              </p>
            ) : null}
          </div>
        ) : null}
      </div>

      {error ? (
        <p
          className={cn(
            "flex items-center truncate text-sm text-destructive",
            ARRIVALS_TILE_CLASS
          )}
          role="alert"
        >
          {error}
        </p>
      ) : null}

      {showEmpty ? (
        <p
          className={cn(
            "flex items-center text-sm text-muted-foreground",
            ARRIVALS_TILE_CLASS
          )}
          role="status"
        >
          {emptyCopy}
        </p>
      ) : null}

      {prepared.layout === "flat" ? (
        <ArrivalsPagedList
          rows={prepared.rows}
          mode={mode}
          pageSize={pageSize}
          classNames={classNames}
        />
      ) : mode === "bus" ? (
        <div
          data-slot="arrivals-groups"
          className={cn("grid grid-cols-1", classNames?.groups)}
        >
          {prepared.groups.map((group, index) => (
            <ArrivalsPagedGroup
              key={group.key}
              group={group}
              mode={mode}
              headingLevel={headingLevel}
              pageSize={pageSize}
              isLastGroup={index === prepared.groups.length - 1}
              classNames={classNames}
            />
          ))}
        </div>
      ) : (
        <div
          data-slot="arrivals-groups"
          className={cn("grid grid-cols-1", classNames?.groups)}
        >
          {prepared.groups.map((group) => (
            <section
              key={group.key}
              data-slot="arrivals-group"
              data-line={group.lineId || undefined}
              className={cn(
                "@container/arrivals-group min-w-0",
                classNames?.group
              )}
            >
              <ArrivalsGroupHeader group={group} headingLevel={headingLevel} />
              <GroupBody
                group={group}
                mode={mode}
                pageSize={pageSize}
                classNames={classNames}
              />
            </section>
          ))}
        </div>
      )}
    </div>
  )
}

"use client"

import { useState, type CSSProperties, type ReactNode } from "react"
import { Play } from "lucide-react"
import { BusNumberChip } from "@/components/tfl/arrivals/bus-number-chip"
import { PlatformChip } from "@/components/tfl/arrivals/platform-chip"
import { LineColorBar } from "@/components/tfl/brand/line-badge"
import { StationName } from "@/components/tfl/station-name"
import { ARRIVALS_LINE_EMPTY_COPY } from "@/lib/tfl/arrivals-empty"
import { COMPASS_BOUND_RE } from "@/lib/tfl/arrivals-bound-sort"
import {
  sliceBoundPage,
  type ArrivalsPreparedBound,
  type ArrivalsPreparedGroup,
  type ArrivalsPreparedRow,
} from "@/lib/tfl/arrivals-prepare"
import { cn } from "@/lib/utils"

type ArrivalsBoardMode = "rail" | "bus"

/**
 * Layout-level class overrides for generated board parts. Each key maps to a
 * stable `data-slot` element. Keep to layout levels — decorative spans, chips,
 * and countdowns are styled through the theme, not this API.
 *
 * - `groups` → `arrivals-groups`: the line / route sections container.
 * - `group` → `arrivals-group`: one line (rail) or route (bus) section. Each
 *   is also a container named `arrivals-group`, so children can respond to the
 *   section's own width.
 * - `subgroups` → `arrivals-subgroups`: rail only — the bounds list inside a
 *   line section.
 * - `subgroup` → `arrivals-subgroup`: rail only — one bound (label + rows).
 * - `rows` → `arrivals-rows`: the arrival rows list (per bound on rail, per
 *   route on grouped bus, the whole list on flat bus).
 */
export type ArrivalsBoardClassNames = {
  groups?: string
  group?: string
  subgroups?: string
  subgroup?: string
  rows?: string
}

/**
 * Keep in sync with `ARRIVALS_TILE_CLASS` / row rule in arrivals-board-view.
 * This file cannot import those constants — the view imports this module.
 */
const TILE_CLASS =
  "box-border h-[var(--arrivals-row)] min-h-[var(--arrivals-row)] max-h-[var(--arrivals-row)] shrink-0 overflow-hidden [content-visibility:auto] [contain-intrinsic-size:auto_3rem]"

const ROW_RULE_CLASS =
  "relative after:pointer-events-none after:absolute after:inset-x-0 after:bottom-0 after:h-px after:bg-border/60"

const LIST_RESET_CLASS = "m-0 ml-0 list-none space-y-0 p-0 [&>li]:mt-0"
const LINE_BAR_BORDER_CLASS = "border-b-4"

export const formatArrivalsCountdown = (seconds?: number): string => {
  if (seconds === undefined || seconds < 0) return "-"
  if (seconds < 60) return "Due"
  return `${Math.floor(seconds / 60)} min`
}

export const getArrivalsPlatformNumber = (
  platformName?: string
): string | null => {
  if (!platformName) return null
  const digit = platformName.match(/(\d+)\s*$/)
  if (digit?.[1]) return digit[1]
  const stripped = platformName
    .replace(COMPASS_BOUND_RE, "")
    .replace(/^\s*[-–—:]\s*/, "")
    .replace(/^platform\s+/i, "")
    .trim()
  return stripped || null
}

export const ArrivalRowItem = ({
  row,
  mode,
  showRule,
}: {
  row: ArrivalsPreparedRow
  mode: ArrivalsBoardMode
  showRule: boolean
}) => {
  const destination =
    row.arrival.towards ?? row.arrival.destinationName ?? "Unknown"
  const platformNumber =
    mode === "rail" ? getArrivalsPlatformNumber(row.arrival.platformName) : null
  const routeLabel =
    mode === "bus"
      ? (row.arrival.lineName ?? row.arrival.lineId ?? "").trim() || null
      : null
  const countdown = formatArrivalsCountdown(row.arrival.timeToStation)
  const rowLabel = [
    platformNumber
      ? `Platform ${platformNumber}`
      : routeLabel
        ? `Route ${routeLabel}`
        : null,
    destination,
    countdown,
  ]
    .filter(Boolean)
    .join(", ")

  return (
    <li
      data-slot="arrivals-row"
      aria-label={rowLabel}
      className={cn(
        "grid grid-cols-[auto_minmax(0,1fr)_auto] items-center gap-x-3 text-sm",
        TILE_CLASS,
        showRule && ROW_RULE_CLASS
      )}
    >
      {mode === "bus" ? (
        routeLabel ? (
          <BusNumberChip label={routeLabel} />
        ) : (
          <span />
        )
      ) : platformNumber ? (
        <PlatformChip number={platformNumber} />
      ) : (
        <span />
      )}
      <div className="min-w-0 overflow-hidden" aria-hidden="true">
        <StationName
          name={destination}
          layout="auto"
          maxLines={2}
          allowAbbreviation
          allowScaleDown
          className="font-medium"
        />
      </div>
      <span className="shrink-0 font-semibold tabular-nums" aria-hidden="true">
        {countdown}
      </span>
    </li>
  )
}

const BoundPager = ({
  label,
  page,
  pageCount,
  onPrev,
  onNext,
}: {
  label: string
  page: number
  pageCount: number
  onPrev: () => void
  onNext: () => void
}) => {
  const atStart = page <= 0
  const atEnd = page >= pageCount - 1

  return (
    <div
      className={cn(
        "ml-auto flex h-6 shrink-0 items-center p-0 text-muted-foreground transition-opacity duration-150",
        "opacity-100 [@media(hover:hover)]:opacity-0",
        "[@media(hover:hover)]:group-hover/bound:opacity-100",
        "[@media(hover:hover)]:group-focus-within/bound:opacity-100"
      )}
    >
      <button
        type="button"
        aria-label={`Previous ${label} arrivals`}
        disabled={atStart}
        onClick={onPrev}
        className="inline-flex h-6 cursor-pointer items-center justify-center pr-1.5 pl-0 text-muted-foreground disabled:pointer-events-none disabled:cursor-default disabled:opacity-25"
      >
        <Play
          className="size-3 -scale-x-100 fill-current stroke-none"
          aria-hidden
        />
      </button>
      <span className="min-w-[2.75ch] text-center text-xs leading-none tabular-nums">
        <span aria-hidden="true">
          {page + 1}/{pageCount}
        </span>
        <span className="sr-only">
          Page {page + 1} of {pageCount}
        </span>
      </span>
      <button
        type="button"
        aria-label={`Next ${label} arrivals`}
        disabled={atEnd}
        onClick={onNext}
        className="inline-flex h-6 cursor-pointer items-center justify-center pr-0 pl-1.5 text-muted-foreground disabled:pointer-events-none disabled:cursor-default disabled:opacity-25"
      >
        <Play className="size-3 fill-current stroke-none" aria-hidden />
      </button>
    </div>
  )
}

export const ArrivalsBoundGroup = ({
  bound,
  mode,
  lineName,
  isLastBound,
  pageSize = 0,
  classNames,
}: {
  bound: ArrivalsPreparedBound
  mode: ArrivalsBoardMode
  lineName: string
  isLastBound: boolean
  pageSize?: number
  classNames?: ArrivalsBoardClassNames
}) => {
  const [page, setPage] = useState(0)
  const canPage = Boolean(bound.label) && pageSize > 0
  const sliced = sliceBoundPage(bound.rows, page, canPage ? pageSize : 0)
  const showPager = canPage
  const visibleRows = sliced.rows
  const showEmpty = visibleRows.length === 0
  const emptyScope = bound.label ? `${lineName} ${bound.label}` : lineName

  const handlePrev = () => {
    setPage((current) =>
      Math.max(0, Math.min(current, sliced.pageCount - 1) - 1)
    )
  }
  const handleNext = () => {
    setPage((current) =>
      Math.min(
        sliced.pageCount - 1,
        Math.min(current, sliced.pageCount - 1) + 1
      )
    )
  }

  return (
    <li
      data-slot="arrivals-subgroup"
      data-bound={bound.label?.toLowerCase()}
      className={cn("group/bound min-w-0", classNames?.subgroup)}
    >
      {bound.label ? (
        <div
          className={cn(
            "flex items-center text-base font-semibold text-muted-foreground",
            TILE_CLASS,
            ROW_RULE_CLASS
          )}
        >
          <span className="min-w-0 flex-1 truncate pr-2">{bound.label}</span>
          {showPager ? (
            <BoundPager
              label={bound.label}
              page={sliced.page}
              pageCount={sliced.pageCount}
              onPrev={handlePrev}
              onNext={handleNext}
            />
          ) : null}
        </div>
      ) : null}
      <ul
        data-slot="arrivals-rows"
        className={cn(LIST_RESET_CLASS, classNames?.rows)}
        role="list"
      >
        {showEmpty ? (
          <li
            data-slot="arrivals-row"
            className={cn(
              "flex items-center text-sm text-muted-foreground",
              TILE_CLASS,
              !isLastBound && ROW_RULE_CLASS
            )}
            aria-label={`${emptyScope}: ${ARRIVALS_LINE_EMPTY_COPY}`}
          >
            {ARRIVALS_LINE_EMPTY_COPY}
          </li>
        ) : (
          visibleRows.map((row, index) => (
            <ArrivalRowItem
              key={row.key}
              row={row}
              mode={mode}
              showRule={
                !(
                  isLastBound &&
                  index === visibleRows.length - 1 &&
                  sliced.padCount === 0
                )
              }
            />
          ))
        )}
        {Array.from({ length: sliced.padCount }, (_, index) => {
          const slotIndex = visibleRows.length + index
          const isLastSlot =
            slotIndex === visibleRows.length + sliced.padCount - 1
          return (
            <li
              key={`pad-${index}`}
              aria-hidden
              className={cn(
                TILE_CLASS,
                !(isLastBound && isLastSlot) && ROW_RULE_CLASS
              )}
            />
          )
        })}
      </ul>
    </li>
  )
}

export const ArrivalsGroupHeader = ({
  group,
  headingLevel,
  pager,
}: {
  group: ArrivalsPreparedGroup
  headingLevel: 1 | 2
  pager?: ReactNode
}) => {
  const LineHeadingTag = headingLevel === 2 ? "h3" : "h2"
  const lineKey = group.kind === "bus-route" ? "buses" : group.lineId
  const stripedBar =
    group.kind === "rail-line" &&
    (group.modeName === "overground" || group.modeName === "elizabeth-line")

  return (
    <header
      data-line={lineKey || undefined}
      className={cn(
        "relative flex items-end pb-2",
        TILE_CLASS,
        !stripedBar && LINE_BAR_BORDER_CLASS
      )}
      style={
        stripedBar
          ? undefined
          : ({
              borderBottomColor: "var(--line-color)",
            } as CSSProperties)
      }
    >
      <LineHeadingTag
        className={cn(
          "m-0 min-w-0 flex-1 truncate pr-2 text-base leading-6 font-semibold text-[var(--line-color)]",
          group.kind === "rail-line" && "tfl-dark-line-text",
          !group.hasInformation && "opacity-70"
        )}
      >
        {group.lineName}
      </LineHeadingTag>
      {pager}
      {stripedBar ? (
        <div
          className="pointer-events-none absolute inset-x-0 bottom-0"
          aria-hidden
        >
          <LineColorBar
            lineId={group.lineId}
            modeName={group.modeName}
            heightClass="h-1"
          />
        </div>
      ) : null}
    </header>
  )
}

const PagedArrivalRows = ({
  rows,
  padCount,
  mode,
  isLast,
  emptyLabel,
}: {
  rows: readonly ArrivalsPreparedRow[]
  padCount: number
  mode: ArrivalsBoardMode
  isLast: boolean
  emptyLabel: string
}) => {
  if (rows.length === 0) {
    return (
      <li
        data-slot="arrivals-row"
        className={cn(
          "flex items-center text-sm text-muted-foreground",
          TILE_CLASS,
          !isLast && ROW_RULE_CLASS
        )}
        aria-label={emptyLabel}
      >
        {ARRIVALS_LINE_EMPTY_COPY}
      </li>
    )
  }

  return (
    <>
      {rows.map((row, index) => (
        <ArrivalRowItem
          key={row.key}
          row={row}
          mode={mode}
          showRule={!(isLast && index === rows.length - 1 && padCount === 0)}
        />
      ))}
      {Array.from({ length: padCount }, (_, index) => {
        const isLastSlot = index === padCount - 1
        return (
          <li
            key={`pad-${index}`}
            aria-hidden
            className={cn(
              TILE_CLASS,
              !(isLast && isLastSlot) && ROW_RULE_CLASS
            )}
          />
        )
      })}
    </>
  )
}

/** Bus grouped-by-route: pager sits on the route header. */
export const ArrivalsPagedGroup = ({
  group,
  mode,
  headingLevel,
  pageSize = 0,
  isLastGroup,
  classNames,
}: {
  group: ArrivalsPreparedGroup
  mode: ArrivalsBoardMode
  headingLevel: 1 | 2
  pageSize?: number
  isLastGroup: boolean
  classNames?: ArrivalsBoardClassNames
}) => {
  const [page, setPage] = useState(0)
  const rows = group.bounds.flatMap((bound) => bound.rows)
  const sliced = sliceBoundPage(rows, page, pageSize)
  const showPager = pageSize > 0

  const handlePrev = () => {
    setPage((current) =>
      Math.max(0, Math.min(current, sliced.pageCount - 1) - 1)
    )
  }
  const handleNext = () => {
    setPage((current) =>
      Math.min(
        sliced.pageCount - 1,
        Math.min(current, sliced.pageCount - 1) + 1
      )
    )
  }

  return (
    <section
      data-slot="arrivals-group"
      data-route={group.lineId || group.lineName}
      className={cn(
        "group/bound @container/arrivals-group min-w-0",
        classNames?.group
      )}
    >
      <ArrivalsGroupHeader
        group={group}
        headingLevel={headingLevel}
        pager={
          showPager ? (
            <BoundPager
              label={group.lineName}
              page={sliced.page}
              pageCount={sliced.pageCount}
              onPrev={handlePrev}
              onNext={handleNext}
            />
          ) : null
        }
      />
      <ul
        data-slot="arrivals-rows"
        className={cn(LIST_RESET_CLASS, classNames?.rows)}
        role="list"
      >
        <PagedArrivalRows
          rows={sliced.rows}
          padCount={sliced.padCount}
          mode={mode}
          isLast={isLastGroup}
          emptyLabel={`${group.lineName}: ${ARRIVALS_LINE_EMPTY_COPY}`}
        />
      </ul>
    </section>
  )
}

